class Bus:
    def __init__(s): s.version = -1; s.data = None; s.obs = []
    def set(s, v):
        s.version += 1; s.data = v
        for o in s.obs: s.notify(o)
    def notify(s, o):
        if o['last'] >= s.version: return
        o['last'] = s.version; o['got'].append(s.data)
    def observe(s, name, sticky=True):
        o = {'name': name, 'last': -1, 'got': []}
        if not sticky: o['last'] = s.version  # 버전을 맞춰 옛 메시지를 건너뛴다
        s.obs.append(o); s.notify(o); return o

b = Bus(); b.set("결제 완료 #1")
a = b.observe("새 화면(기본)"); c = b.observe("새 화면(non-sticky)", sticky=False)
b.set("결제 완료 #2")
print(a['name'], a['got'])
print(c['name'], c['got'])
# 새 화면(기본) ['결제 완료 #1', '결제 완료 #2']
# 새 화면(non-sticky) ['결제 완료 #2']

pending = None; queue = []; delivered = []
def post_value(v):
    global pending
    first = pending is None
    pending = v
    if first: queue.append(lambda: delivered.append(pending))
for v in ["카드 등록", "쿠폰 적용", "결제 요청"]: post_value(v)
for r in queue: r()
print("기본 postValue:", delivered)
# 기본 postValue: ['결제 요청']
